  // Profil paneli · üye ekle · başlık menüleri — SPEC-MESAJLAR §15–§17.
  //
  // Metinler SPEC'ten birebir alındı. İki bilinçli sapma var ve ikisi de
  // `lib/messages/metrics.ts` içindeki sapma listesinde kayıtlı:
  //
  //   1. Şifreleme satırı (§15.5). Tasarım "Uçtan uca şifreli · Anahtar doğrulandı" diyor;
  //      üründe uçtan uca şifreleme yok. Yapılmayan bir şeyi iddia eden satır yayınlanmaz,
  //      metin aktarım şifrelemesini söyler. Ölçü ve renk tasarımdaki gibi kalır.
  //   2. `Süresiz` sessizliğin toast'ı SPEC'in on iki satırlık listesinde yok; referans
  //      HTML `Sohbet süresiz sessize alındı` basıyor ve otorite HTML'dir.
  //
  // **Rozet adı ve açıklaması burada yok.** İkisi de `@wizards/types` içindeki
  // `BADGE_CATALOG.copy` alanından gelir (o dosya "her iki platform adları ve açıklamaları
  // buradan okur, sözlüklerde bilerek yoktur" diyor). SPEC'in altı örnek açıklaması
